---@alias gcp.unstable.containeranalysis_v1alpha1.FileNoteFileTypeEnum "FILE_TYPE_UNSPECIFIED"|"SOURCE"|"BINARY"|"ARCHIVE"|"APPLICATION"|"AUDIO"|"IMAGE"|"TEXT"|"VIDEO"|"DOCUMENTATION"|"SPDX"|"OTHER"

